from dataclasses import dataclass

@dataclass
class Item:
    id: str
    name: str

themes.stylesheet:
QWidget { background: #22212c; color: #f8f8f2; }
QMainWindow, QDialog { background: #22212c; }
QMenuBar, QMenu { background: #282a36; color: #f8f8f2; }
QToolBar { background: #282a36; border: 0; }
QPushButton { background: #454158; color: #f8f8f2; border: 1px solid #6272a4; border-radius: 4px; padding: 4px 8px; }
QLineEdit, QTextEdit, QPlainTextEdit, QTreeView, QListWidget { background: #1c1a24; border: 1px solid #454158; color: #f8f8f2; }
QTabBar::tab { background: #282a36; color: #959da5; padding: 6px 12px; }
QTabBar::tab:selected { background: #454158; color: #50fa7b; font-weight: bold; }
QStatusBar { background: #19181f; color: #8be9fd; }
